INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-spring-am-29','exam-sg','電子署名・真正性','standard','single_choice','【平成30年度 春期 午前 問29】ディジタル証明書をもつA氏が，B商店に対して電子メールを使って商品を注文するときに，A氏は自分の秘密鍵を用いてディジタル署名を行い，B商店はA氏の公開鍵を用いて署名を確認する。この手法によって実現できることはどれか。A氏の秘密鍵はA氏だけが使用できるものとする。','[{"id":"a","text":"A氏からB商店に送られた注文の内容が，第三者に漏れないようにできる。"},{"id":"b","text":"A氏から発信された注文が，B商店に届くようにできる。"},{"id":"c","text":"B商店からA氏への商品販売が許可されていることを確認できる。"},{"id":"d","text":"B商店に届いた注文が，A氏からの注文であることを確認できる。"}]','"d"','送信者の秘密鍵によるディジタル署名を公開鍵で検証することで，署名者の確認と改ざん検知ができる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-30','exam-sg','PKI・認証局','standard','single_choice','【平成30年度 春期 午前 問30】PKI（公開鍵基盤）において，認証局が果たす役割の一つはどれか。','[{"id":"a","text":"共通鍵を生成する。"},{"id":"b","text":"公開鍵を利用してデータを暗号化する。"},{"id":"c","text":"失効したディジタル証明書の一覧を発行する。"},{"id":"d","text":"データが改ざんされていないことを検証する。"}]','"c"','認証局は証明書の発行・失効管理を行い，失効した証明書の一覧（CRL）を発行する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-31','exam-sg','サイバーセキュリティ基本法','standard','single_choice','【平成30年度 春期 午前 問31】サイバーセキュリティ基本法の説明はどれか。','[{"id":"a","text":"国民は，サイバーセキュリティの重要性に関する関心と理解を深め，その確保に必要な注意を払うよう努めるものとすると規定している。"},{"id":"b","text":"国及び情報通信事業者の責務だけを定め，地方公共団体や教育研究機関には言及していない。"},{"id":"c","text":"国及び地方公共団体の責務を定め，民間事業者が努力すべき事項についての規定はない。"},{"id":"d","text":"地方公共団体を重要社会基盤事業者と位置づけ，関連施策の立案・実施に責任を負うと規定している。"}]','"a"','同法は国民の理解と関心を深め，サイバーセキュリティ確保に必要な注意を払う努力についても定めている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-32','exam-sg','情報セキュリティ関連法規・刑法','standard','single_choice','【平成30年度 春期 午前 問32】記憶媒体を介して企業で使用されているコンピュータにマルウェアを侵入させ，そのコンピュータの記憶内容を消去した者を処罰の対象とする法律はどれか。','[{"id":"a","text":"刑法"},{"id":"b","text":"製造物責任法"},{"id":"c","text":"不正アクセス禁止法"},{"id":"d","text":"プロバイダ責任制限法"}]','"a"','記憶内容を消去するなどの行為は，刑法の電子計算機損壊等業務妨害罪などが問題となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-33','exam-sg','個人情報保護法・要配慮個人情報','standard','single_choice','【平成30年度 春期 午前 問33】個人情報保護委員会のガイドラインにおいて，要配慮個人情報として例示されているものはどれか。','[{"id":"a","text":"医療従事者が診療の過程で知り得た診療記録などの情報"},{"id":"b","text":"国籍や外国人であるという法的地位の情報"},{"id":"c","text":"宗教に関する書籍の購買や貸出しに係る情報"},{"id":"d","text":"他人を被疑者とする犯罪捜査のために取調べを受けた事実"}]','"a"','病歴などの医療情報は要配慮個人情報に該当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-34','exam-sg','著作権法・プログラム','standard','single_choice','【平成30年度 春期 午前 問34】A社が著作権を保有しているプログラムで実現している機能と，B社のプログラムが同じ機能をもつとき，A社に対するB社の著作権侵害に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"A社のソースコードを無断使用しても，A社公表後1年未満にB社が公表すれば侵害にならない。"},{"id":"b","text":"A社のソースコードを無断使用しても，プログラム名称を別名称にすれば侵害にならない。"},{"id":"c","text":"A社のソースコードを無断使用していると，著作権の存続期間内は著作権侵害となる。"},{"id":"d","text":"同じ機能を実現していれば，ソースコードの記述によらず著作権侵害となる。"}]','"c"','プログラムのソースコードを無断で複製・利用すれば，著作権侵害となり得る。同じ機能であることだけでは侵害とは限らない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-35','exam-sg','不正競争防止法','standard','single_choice','【平成30年度 春期 午前 問35】不正競争防止法で禁止されている行為はどれか。','[{"id":"a","text":"競争相手に対抗するために，特定商品の小売価格を安価に設定する。"},{"id":"b","text":"自社製品を扱う小売業者に，指定した小売価格で販売するよう指示する。"},{"id":"c","text":"他社のヒット商品と商品名や形状は異なるが，同等の機能をもつ商品を販売する。"},{"id":"d","text":"広く知られた他人の商品の表示に自社商品の表示を類似させ，他人の商品と誤認させて販売する。"}]','"d"','周知な他人の商品等表示と類似する表示を使用し，混同を生じさせる行為は不正競争に該当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja');
